    export const getGetCompanionFrameUrl = (companionId: number,
    frameId: number,
    params?: GetCompanionFrameParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/v1/companions/${companionId}/frames/${frameId}/image?${stringifiedParams}` : `/api/v1/companions/${companionId}/frames/${frameId}/image`
}

